import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Problemi di secondo grado di tipo numerico","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/a_algebra/ah/ahda.md","filePath":"lezioni/a_algebra/ah/ahda.md"}`),a={name:`lezioni/a_algebra/ah/ahda.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="problemi-di-secondo-grado-di-tipo-numerico" tabindex="-1">Problemi di secondo grado di tipo numerico <a class="header-anchor" href="#problemi-di-secondo-grado-di-tipo-numerico" aria-label="Permalink to “Problemi di secondo grado di tipo numerico”">​</a></h1><p>Vediamo direttamente su alcuni esercizi come risolvere un problema di secondo grado di tipo numerico: di solito l&#39;equazione risolvente di secondo grado viene suggerita direttamente dal problema stesso;</p><blockquote><p>per trovare l&#39;equazione risolvente potrai usare indifferentemente una o due incognite, come ti sembrerà più semplice: se userai due incognite troverai un sistema: risolvendolo con il metodo di sostituzione troverai l&#39;equazione risolvente che, nei problemi di secondo grado, sarà un&#39;equazione di secondo grado</p></blockquote><p class="text-blue">[1) Trovare quel numero che, sommato al suo quadrato, dia come risultato <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>20</mn></mrow><annotation encoding="application/x-tex">20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">20</span></span></span></span>]</p><p><a href="./ahda1.html">soluzione</a></p><hr><p class="text-blue">[2) determinare due numeri sapendo che la loro differenza vale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> e che la somma dei loro quadrati vale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>41</mn></mrow><annotation encoding="application/x-tex">41</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">41</span></span></span></span>]</p><p><a href="./ahda2.html">soluzione</a></p><hr><p class="text-blue">[3) trovare due numeri sapendo che la loro somma vale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>7</mn></mrow><annotation encoding="application/x-tex">7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">7</span></span></span></span> ed il loro prodotto vale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>12</mn></mrow><annotation encoding="application/x-tex">12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">12</span></span></span></span>]</p><p><a href="./../af/afccgea.html">soluzione</a></p><p>è il <a href="./../af/afccdc.html">classico problema</a> di applicazione delle equazioni di secondo grado; altri <a href="./../af/afccge.html">esercizi</a> vedere anche i <a href="./../ai/aicea.html">sistemi simmetrici</a></p><hr><p class="text-blue">[4) Considerate un numero di due cifre: il prodotto delle due cifre vale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>40</mn></mrow><annotation encoding="application/x-tex">40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">40</span></span></span></span>; se si invertono le cifre il numero diminuisce di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>27</mn></mrow><annotation encoding="application/x-tex">27</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">27</span></span></span></span>. Trovare il numero]</p><p><a href="./ahda4.html">soluzione</a></p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};